void sock_to_str(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    char buffer[NI_MAXHOST];
    const char *proto = c->transport == ascii ? "ascii" : "binary";
    const char *ip_str = "";

    if (af == AF_INET || af == AF_INET6) {
        void *ip_ptr = NULL;
        in_port_t port = 0;

        if (af == AF_INET) {
            ip_ptr = &((struct sockaddr_in *)sock_addr)->sin_addr;
            port = ntohs(((struct sockaddr_in *)sock_addr)->sin_port);
        } else {
            ip_ptr = &((struct sockaddr_in6 *)sock_addr)->sin6_addr;
            port = ntohs(((struct sockaddr_in6 *)sock_addr)->sin6_port);
        }

        if (ip_ptr != NULL && inet_ntop(af, ip_ptr, buffer, sizeof(buffer)) != NULL) {
            ip_str = buffer;
        }

        if (port != 0) {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://%s:%hu", proto, ip_str, port);
        } else {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://%s", proto, ip_str);
        }
    } else if (af == AF_UNIX) {
        if (((struct sockaddr_un *)sock_addr)->sun_path[0] != '\0') {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://%s", proto, ((struct sockaddr_un *)sock_addr)->sun_path);
        } else {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://<UNIX socket with empty path>", proto);
        }
    } else {
        snprintf(addr, MAX_ADDRSTRLEN, "%s://<unknown address family %d>", proto, af);
    }
}

void conn_sockaddr_to_str(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    const char *proto = (c->transport == tcp_transport) ? "tcp" : "udp";
    const char *ip_str = "";
    in_port_t port = 0;

    switch (af) {
        case AF_INET: {
            struct sockaddr_in *saddr_in = (struct sockaddr_in *)sock_addr;
            ip_str = inet_ntop(AF_INET, &saddr_in->sin_addr, addr, INET_ADDRSTRLEN);
            port = ntohs(saddr_in->sin_port);
            break;
        }
        case AF_INET6: {
            struct sockaddr_in6 *saddr_in6 = (struct sockaddr_in6 *)sock_addr;
            ip_str = inet_ntop(AF_INET6, &saddr_in6->sin6_addr, addr, INET6_ADDRSTRLEN);
            port = ntohs(saddr_in6->sin6_port);
            break;
        }
        case AF_UNIX: {
            struct sockaddr_un *saddr_un = (struct sockaddr_un *)sock_addr;
            snprintf(addr, MAX_PATH, "%s", saddr_un->sun_path);
            break;
        }
        default:
            snprintf(addr, MAX_PATH, "<unknown af %d>", af);
            return;
    }

    if (af == AF_UNIX) {
        snprintf(addr, MAX_PATH, "%s://%s", proto, ip_str);
    } else {
        if (strlen(ip_str) == 0) {
            snprintf(addr, MAX_PATH, "%s://<unknown address>", proto);
        } else {
            snprintf(addr, MAX_PATH, "%s://%s:%hu", proto, ip_str, port);
        }
    }
}

void sock_to_str(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    char buffer[INET6_ADDRSTRLEN];
    const char *proto = "unknown";

    if (c != NULL) {
        proto = c->transport == ascii ? "ascii" : "binary";
    }

    if (af == AF_INET || af == AF_INET6) {
        void *ip_ptr = NULL;
        uint16_t port = 0;

        if (af == AF_INET) {
            ip_ptr = &(((struct sockaddr_in *)sock_addr)->sin_addr);
            port = ntohs(((struct sockaddr_in *)sock_addr)->sin_port);
        } else if (af == AF_INET6) {
            ip_ptr = &(((struct sockaddr_in6 *)sock_addr)->sin6_addr);
            port = ntohs(((struct sockaddr_in6 *)sock_addr)->sin6_port);
        }

        if (ip_ptr != NULL) {
            if (inet_ntop(af, ip_ptr, buffer, sizeof(buffer)) != NULL) {
                snprintf(addr, MAX_ADDRSTRLEN, "%s://%s:%d", proto, buffer, port);
            }
        }
    } else if (af == AF_UNIX) {
        struct sockaddr_un *un = (struct sockaddr_un *)sock_addr;
        if (un->sun_path[0] != '\0') {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://%s", proto, un->sun_path);
        } else {
            snprintf(addr, MAX_ADDRSTRLEN, "%s://unix:abstract", proto);
        }
    }

    if (addr[0] == '\0') {
        snprintf(addr, MAX_ADDRSTRLEN, "%s://%d", proto, af);
    }
}

void conn_sockaddr_to_str(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    int port = 0;
    const char *proto = (c->transport == tcp_transport) ? "tcp" : "udp";

    if (af == AF_INET) {
        struct sockaddr_in *sa_in = (struct sockaddr_in *)sock_addr;
        const char *ip = inet_ntop(AF_INET, &(sa_in->sin_addr), addr, INET_ADDRSTRLEN);
        if (ip) {
            port = ntohs(sa_in->sin_port);
        }
    } else if (af == AF_INET6) {
        struct sockaddr_in6 *sa_in6 = (struct sockaddr_in6 *)sock_addr;
        const char *ip = inet_ntop(AF_INET6, &(sa_in6->sin6_addr), addr, INET6_ADDRSTRLEN);
        if (ip) {
            port = ntohs(sa_in6->sin6_port);
        }
    } else if (af == AF_UNIX) {
        struct sockaddr_un *sa_un = (struct sockaddr_un *)sock_addr;
        if (sa_un->sun_path[0] != '\0') {
            strncpy(addr, sa_un->sun_path, MAX_PATH);
        } else {
            snprintf(addr, MAX_PATH, "abstract-unix-socket");
        }
        return;
    } else {
        snprintf(addr, MAX_PATH, "unknown-af(%d)", af);
        return;
    }

    if (addr[0] == '\0') {
        snprintf(addr, MAX_PATH, "unknown-%s", proto);
    }

    if (port != 0) {
        snprintf(addr, MAX_PATH, "%s:%d", addr, port);
    }
}

void conn_sockaddr_to_str(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    const char *proto = (c->transport == tcp_transport) ? "tcp" : "udp";
    const char *ip_str = "";
    in_port_t port = 0;

    if (af == AF_INET) {
        struct sockaddr_in *s = (struct sockaddr_in *)sock_addr;
        ip_str = inet_ntop(AF_INET, &s->sin_addr, addr, INET_ADDRSTRLEN);
        port = ntohs(s->sin_port);
    } else if (af == AF_INET6) {
        struct sockaddr_in6 *s = (struct sockaddr_in6 *)sock_addr;
        ip_str = inet_ntop(AF_INET6, &s->sin6_addr, addr, INET6_ADDRSTRLEN);
        port = ntohs(s->sin6_port);
    } else if (af == AF_UNIX) {
        struct sockaddr_un *s = (struct sockaddr_un *)sock_addr;
        strncpy(addr, s->sun_path, MAXPATHLEN);
    }

    if (ip_str == NULL || *ip_str == '\0') {
        snprintf(addr, MAXPATHLEN, "<%s>", (af == AF_UNIX) ? "unix" : (af == AF_INET) ? "ipv4" : "ipv6");
    } else if (af == AF_UNIX) {
        // No port for AF_UNIX
        snprintf(addr, MAXPATHLEN, "%s", addr);
    } else {
        snprintf(addr, MAXPATHLEN, "%s://%s:%hu", proto, ip_str, port);
    }
}
